draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw book
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.fillStyle = '#dfd5c5';
  ctx.beginPath();
  ctx.rect(W/2-50, H/2-70, 100, 140);
  ctx.fill();
  ctx.stroke();

  // draw stick figure
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2+50, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+30);
  ctx.lineTo(W/2, H/2+70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+50);
  ctx.lineTo(W/2-30, H/2+80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+50);
  ctx.lineTo(W/2+30, H/2+80);
  ctx.stroke();

  // draw reading stick figure with book
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+70);
  ctx.lineTo(W/2, H/2+100 + 20 * Math.sin(t));
  ctx.stroke();

  // draw wisdom
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Wisdom', W/2, H/2-120 + 20 * Math.cos(t));

  ctx.restore();
}
